CREATE FUNCTION chk_k13() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c2 IS NOT NULL AND NEW.c3 IS NOT NULL AND NEW.c4 IS NOT NULL AND NEW.c5 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c4 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c3=NEW.c3 AND c4=NEW.c4 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c4 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c3=NEW.c3 AND c4=NEW.c4 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c4 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c4=NEW.c4 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c3=NEW.c3 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c4 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c3=NEW.c3 AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c4 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c4=NEW.c4 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NULL AND c3 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c3=NEW.c3 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NULL AND c3 IS NOT NULL AND c4 IS NOT NULL AND c1=NEW.c1 AND c3=NEW.c3 AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c4 IS NULL AND c2 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c5 IS NULL AND c2 IS NOT NULL AND c4 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c4 IS NULL AND c5 IS NULL AND c2 IS NOT NULL AND c3 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c4 IS NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c5 IS NULL AND c4 IS NOT NULL AND c1=NEW.c1 AND c4=NEW.c4) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c4 IS NULL AND c5 IS NULL AND c3 IS NOT NULL AND c1=NEW.c1 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c4 IS NULL AND c5 IS NULL AND c2 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL AND c4 IS NULL AND c5 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k13 violated'; END IF;
